items.description:
/etc/apt/apt.conf.d/50unattended-upgrades needs the line set to:

Unattended-Upgrade::Mail "backup\.logs@example.com";

sed -i 's|^//Unattended-Upgrade::Mail "";|Unattended-Upgrade::Mail "backup.logs@example.com";|' /etc/apt/apt.conf.d/50unattended-upgrades

/etc/apt/apt.conf.d/50unattended-upgrades needs the line set to:

Unattended-Upgrade::MailReport "on-change";

sed -i 's|^//Unattended-Upgrade::MailReport "on-change";|Unattended-Upgrade::MailReport "on-change";|' /etc/apt/apt.conf.d/50unattended-upgrades

parameters:
var r = JSON.parse(value), out = [];
[['vms','VM'],['lxc','CT']].forEach(function (p) {
  (r[p[0]] || []).forEach(function (g) {
    if (g.template) return;
    out.push({'{#VMID}': String(g.vmid), '{#NAME}': g.name, '{#TYPE}': p[1], '{#ARRAY}': p[0]});
  });
});
return JSON.stringify(out);
